import { readFileSync } from 'node:fs';

const ARTIFACT = { spike: 'probe', bounded: 'chat-design', architectural: 'spec' };

let text;
try {
  text = readFileSync(process.argv[2], 'utf8');
} catch {
  process.exit(1);
}

const fields = {};
for (const line of text.split('\n')) {
  const m = /^\s*([A-Za-z][A-Za-z-]*)\s*:\s*(\S+)\s*$/.exec(line);
  if (m) fields[m[1].toLowerCase()] = m[2].toLowerCase();
}

const yes = (k) => fields[k] === 'yes';

const path = yes('shared-interface')
  ? 'architectural'
  : yes('question')
    ? 'spike'
    : yes('existing-flow')
      ? 'bounded'
      : 'architectural';

process.stdout.write(path + '\n' + ARTIFACT[path] + '\n');
